export enum UserRole {
  SUPERADMIN = 'SUPERADMIN', // Auditoría y Control Maestro
  ADMIN = 'ADMIN',           // Gestión Central: Recepción y Derivación
  HEAD = 'HEAD',            // Jefatura de Área: Gestión de Recursos y Asignación
  ANALYST = 'ANALYST'       // Cuerpo Técnico: Ejecución y Resolución
}

export enum Area {
  CONTABILIDAD = 'Contabilidad',
  RRHH = 'RRHH',
  ACREDITACION = 'Acreditación',
  FINANZAS = 'Finanzas'
}

export enum Status {
  RECIBIDO = 'Recibido',      // Bandeja de Entrada Central (Admin)
  DERIVACION = 'En Derivación', // Asignado a un Área (Jefe de Área)
  EJECUCION = 'En Ejecución',   // En trabajo activo por un Analista
  FINALIZADO = 'Finalizado'     // Requerimiento resuelto y auditado
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export type UserStatus = 'ACTIVE' | 'INACTIVE';
export type ViewMode = 'work' | 'superadmin';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  area?: Area; 
  password?: string;
  status?: UserStatus;
  joinedAt?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
  role: UserRole;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; 
  assignedAnalyst?: string; 
  logs: LogEntry[];
  createdAt: string;
  lastUpdated: string;
  finishedAt?: string;
  isReturned?: boolean; 
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        console.error("CRITICAL: SISREQ Storage Layer Failure", error);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    if (user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN) {
      setGlobalFilterArea('ALL');
    } else {
      setGlobalFilterArea(user.area as Area);
    }
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;

    // El SuperAdmin y el Admin Central ven todo.
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;

    // Jefes y Analistas ven solo su área si ya ha sido derivada de Central.
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;

    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no identificada.' };
    if (req.status === target) return { allowed: true };

    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    if (req.status === Status.FINALIZADO && activeRole !== UserRole.SUPERADMIN) {
      return { allowed: false, reason: 'Solo Auditoría Superior puede reabrir requerimientos cerrados.' };
    }

    switch (activeRole) {
      case UserRole.ADMIN:
        if (req.status === Status.RECIBIDO && target === Status.DERIVACION) return { allowed: true };
        if (target === Status.FINALIZADO && req.status === Status.EJECUCION) return { allowed: true }; // Admin puede cerrar por emergencia
        return { allowed: false, reason: 'Labor administrativa limitada a derivación o cierre central.' };

      case UserRole.HEAD:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'No tiene jurisdicción sobre esta unidad operativa.' };

        if (req.status === Status.DERIVACION && target === Status.EJECUCION) {
          if (!req.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un analista antes de iniciar ejecución.' };
          return { allowed: true };
        }
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'Transición no permitida para Jefatura en este estado.' };

      case UserRole.ANALYST:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción técnica ajena.' };
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'El analista solo puede cerrar tickets en ejecución activa.' };

      default:
        return { allowed: false, reason: 'Rol sin facultades de transición de estados.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: Status.RECIBIDO,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro formal de requerimiento en sistema central',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const isReturningToCentral = newStatus === Status.RECIBIDO;

    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      assignedAnalyst: isReturningToCentral ? undefined : req.assignedAnalyst,
      isReturned: isReturningToCentral ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `TRANSICIÓN: El ticket ha pasado al estado [${newStatus.toUpperCase()}]`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN A CENTRAL: ${reason}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN: Analista [${analystName}] designado como responsable técnico`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: message.trim(),
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'MODIFICACIÓN: Actualización de metadatos y contenido del ticket',
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = {
      id: genId('U'),
      name: name.trim(),
      email: email.trim(),
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, Area } from '../types';
import { LayoutDashboard, Plus, Briefcase, LogOut, Shield, ArrowLeftRight } from 'lucide-react';
import { NewRequestModal } from './NewRequestModal';
import { RequestDetailModal } from './RequestDetailModal';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { currentUser, logout, viewMode, setViewMode, activeRole, setActiveRole, setGlobalFilterArea, setSelectedRequestId } = useSisreq();
  const [isModalOpen, setIsModalOpen] = useState(false);

  if (!currentUser) return null;

  const getInitials = (name: string) => name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);

  // Lógica para detectar si el usuario tiene capacidad híbrida (Admin con Área asignada)
  const isHybridUser = currentUser.role === UserRole.ADMIN && !!currentUser.area;

  const handleToggleProfile = () => {
    setSelectedRequestId(null);

    if (activeRole === UserRole.ADMIN) {
        setActiveRole(UserRole.HEAD);
        setGlobalFilterArea(currentUser.area as Area);
    } else {
        setActiveRole(UserRole.ADMIN);
        setGlobalFilterArea('ALL');
    }
  };

  const getRoleBadge = () => {
    if (isHybridUser) {
        return (
            <button 
                onClick={handleToggleProfile}
                className={`flex items-center gap-1.5 px-2 py-0.5 rounded-lg text-[9px] font-bold border transition-all ${
                    activeRole === UserRole.ADMIN 
                    ? 'bg-red-50 text-red-600 border-red-100 hover:bg-red-100' 
                    : 'bg-indigo-50 text-indigo-600 border-indigo-100 hover:bg-indigo-100'
                }`}
            >
                <ArrowLeftRight size={10} />
                {activeRole === UserRole.ADMIN ? 'MODO ADMIN' : `JEFE ${currentUser.area?.toUpperCase()}`}
            </button>
        );
    }

    switch (currentUser.role) {
        case UserRole.SUPERADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-900 text-white font-bold border border-slate-950 tracking-wider">SUPERADMIN</span>;
        case UserRole.ADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-red-50 text-red-600 font-bold border border-red-100 tracking-wider uppercase">ADMIN CENTRAL</span>;
        case UserRole.HEAD: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-indigo-50 text-indigo-600 font-bold border border-indigo-100 tracking-wider uppercase">JEFE {currentUser.area}</span>;
        default: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-100 text-slate-500 font-bold border border-slate-200 tracking-wider uppercase">ANALYST</span>;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200/60 z-30 shrink-0 h-16 px-6 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-8">
            <div className="flex items-center gap-3 pr-8 border-r border-slate-200/50">
                <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-100">
                    <LayoutDashboard size={20} strokeWidth={2.5} />
                </div>
                <h1 className="text-lg font-black tracking-tighter text-slate-900 leading-none">SISREQ</h1>
            </div>

            <nav className="flex items-center gap-6">
                {currentUser.role === UserRole.SUPERADMIN ? (
                    <div className="flex bg-slate-100 p-1 rounded-xl gap-1 border border-slate-200/50">
                        <button 
                            onClick={() => setViewMode('work')} 
                            className={`px-5 py-1.5 rounded-lg transition-all text-xs font-black uppercase tracking-widest ${viewMode === 'work' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                        >
                            Operativo
                        </button>
                        <button 
                            onClick={() => setViewMode('superadmin')} 
                            className={`px-5 py-1.5 rounded-lg transition-all text-xs font-black uppercase tracking-widest ${viewMode === 'superadmin' ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                        >
                            Master
                        </button>
                    </div>
                ) : (
                    <div className="flex items-center gap-2.5 px-4 py-1.5 bg-slate-50 rounded-full border border-slate-100">
                        {activeRole === UserRole.ADMIN ? <Shield size={14} className="text-red-500"/> : <Briefcase size={14} className="text-indigo-500"/>}
                        <span className="text-[11px] font-black uppercase tracking-[0.1em] text-slate-600">
                            {activeRole === UserRole.ADMIN ? 'Consola de Control Central' : `${activeRole} • ${currentUser.area || 'General'}`}
                        </span>
                    </div>
                )}
            </nav>
        </div>

        <div className="flex items-center gap-5">
            {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) && (
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2 rounded-xl flex items-center gap-2.5 text-xs font-black uppercase tracking-widest transition-all shadow-xl shadow-indigo-100 active:scale-95 group"
                >
                    <Plus size={16} strokeWidth={3} className="group-hover:rotate-90 transition-transform" /> 
                    Nuevo Requerimiento
                </button>
            )}

            <div className="h-8 w-px bg-slate-200 mx-1"></div>

            <div className="flex items-center gap-4">
                <div className="flex flex-col items-end">
                    <span className="text-sm font-black text-slate-800 leading-none mb-1.5">{currentUser.name}</span>
                    {getRoleBadge()}
                </div>
                <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-slate-100 to-slate-200 border border-white shadow-sm flex items-center justify-center font-black text-xs text-slate-600 shrink-0 ring-4 ring-slate-50">
                    {getInitials(currentUser.name)}
                </div>
                <button 
                    onClick={logout} 
                    className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" 
                    title="Cerrar Sesión"
                >
                    <LogOut size={20} />
                </button>
            </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0 relative z-10">
        {children}
        <div className="absolute inset-0 opacity-[0.15] pointer-events-none z-[-1]" 
             style={{backgroundImage: 'radial-gradient(#94a3b8 1px, transparent 1px)', backgroundSize: '30px 30px'}}>
        </div>
      </main>

      <NewRequestModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      <RequestDetailModal />
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area, UserRole } from '../types';
import { Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown, LayoutGrid } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, updateStatus, globalFilterArea, setGlobalFilterArea, activeRole, canUserSeeRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        alert(`RESTRICCIÓN DE FLUJO SISREQ:\n${err.message}`);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={18} />, color: 'indigo' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} />, color: 'orange' },
    { title: 'Ejecución Técnica', status: Status.EJECUCION, icon: <PlayCircle size={18} />, color: 'amber' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={18} />, color: 'emerald' }
  ];

  return (
    <div className="flex flex-col h-full">
      <div className="px-8 py-6 flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white/50 backdrop-blur-sm border-b border-slate-200/50 shadow-sm z-20">
          <div className="flex items-center gap-6">
             <div className="flex flex-col">
                 <div className="flex items-center gap-3 mb-1.5">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] leading-none">
                        Tablero de Operaciones
                    </h2>
                 </div>
                 <div className="flex items-center gap-4">
                    <span className="text-2xl font-black text-slate-900 tracking-tighter">Ciclo de Vida</span>
                    <span className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-[10px] font-black border border-indigo-100 shadow-sm">
                        {filteredRequests.length} REQUERIMIENTOS
                    </span>
                 </div>
             </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar por ID, Asunto o Analista..." 
                    className="w-full min-w-[350px] pl-12 pr-6 py-3 text-sm font-bold bg-white border-2 border-slate-100 rounded-2xl focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-300 shadow-inner"
                />
             </div>

             {(activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                <div className="relative">
                    <LayoutGrid size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="pl-12 pr-10 py-3 text-xs font-black bg-white border-2 border-slate-100 rounded-2xl appearance-none cursor-pointer outline-none focus:border-indigo-500 transition-all uppercase tracking-[0.15em] text-slate-600 shadow-sm"
                    >
                        <option value="ALL">Jurisdicción Global</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a.toUpperCase()}</option>)}
                    </select>
                    <ChevronDown size={16} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
          <div className="h-full flex px-8 py-10 gap-10 min-w-[1400px]">
              {COLUMNS.map((col) => {
                  if (col.status === Status.RECIBIDO && activeRole !== UserRole.ADMIN && activeRole !== UserRole.SUPERADMIN) return null;

                  const items = filteredRequests.filter(r => r.status === col.status);
                  const isDragActive = dragOverColumn === col.status;

                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col min-w-[320px] max-w-[400px] rounded-[3rem] transition-all duration-300 ${isDragActive ? 'bg-indigo-50/70 ring-2 ring-indigo-200 ring-dashed scale-[1.02]' : 'bg-transparent'}`} 
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                          onDragLeave={() => setDragOverColumn(null)} 
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          <div className="flex items-center justify-between px-8 py-5 bg-white border border-slate-100 rounded-3xl mb-8 shadow-sm ring-1 ring-black/5">
                              <div className="flex items-center gap-4">
                                  <div className={`p-3 rounded-2xl bg-${col.color}-50 text-${col.color}-600 shadow-inner`}>{col.icon}</div>
                                  <span className={`text-[11px] font-black uppercase tracking-[0.2em] text-slate-700`}>{col.title}</span>
                              </div>
                              <span className="bg-slate-100 text-slate-500 px-3 py-1.5 rounded-xl text-[10px] font-black border border-slate-200">{items.length}</span>
                          </div>

                          <div className="flex-1 overflow-y-auto px-2 pb-24 custom-scrollbar space-y-6">
                              {items.map(req => <RequestCard key={req.id} data={req} />)}
                              {items.length === 0 && (
                                  <div className="flex flex-col items-center justify-center h-48 border-4 border-dashed border-slate-200/50 rounded-[3rem] text-slate-300">
                                      <div className="mb-4 opacity-20 transform scale-150">{col.icon}</div>
                                      <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">Sin Pendientes</p>
                                  </div>
                              )}
                          </div>
                      </div>
                  )
              })}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { PRIORITY_STYLES } from '../constants';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2, AlertCircle } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId, activeRole } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  const isDraggable = () => {
    if (!currentUser || !activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN) return true;

    if (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) return true;

    if (data.area === currentUser.area) {
        if (activeRole === UserRole.HEAD) {
            if (data.status === Status.DERIVACION && !!data.assignedAnalyst) return true;
            if (data.status === Status.EJECUCION) return true;
        }
        if (activeRole === UserRole.ANALYST && data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    if (!isDraggable()) {
        e.preventDefault();
        return;
    }
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';

    const dragGhost = e.currentTarget as HTMLElement;
    dragGhost.style.opacity = '0.4';
    setTimeout(() => {
        if (dragGhost) dragGhost.style.opacity = '1';
    }, 0);
  };

  const handleCardClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-500';
        case Status.DERIVACION: return 'border-orange-500';
        case Status.EJECUCION: return 'border-amber-500';
        case Status.FINALIZADO: return 'border-emerald-500';
        default: return 'border-slate-300';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-2xl relative group animate-in fade-in slide-in-from-bottom-2 duration-300
            transition-all duration-300 ease-out
            shadow-[0_4px_20px_-10px_rgba(0,0,0,0.1)] hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.15)]
            border border-slate-100
            border-l-[6px]
            cursor-pointer flex flex-col
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'hover:bg-indigo-50/10 active:scale-[0.98]' : 'cursor-default'}
            ${isMinimized ? 'h-[64px] py-3 px-6' : 'min-h-[190px] p-6'}
        `}
    >
      <div className={`flex justify-between items-center shrink-0 ${isMinimized ? '' : 'mb-4'}`}>
        <div className="flex items-center gap-3">
            {isDraggable() && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="p-1 -ml-2 text-slate-200 group-hover:text-indigo-400 cursor-grab active:cursor-grabbing transition-colors">
                    <GripVertical size={14} />
                </div>
            )}
            <div className="flex items-center gap-2">
                <span className="flex items-center gap-1 font-mono text-[10px] text-slate-400 font-black uppercase tracking-tighter">
                    <Hash size={10} className="opacity-40" /> {data.id.split('-')[1]}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[9px] bg-red-600 text-white px-2 py-0.5 rounded-md font-black tracking-widest flex items-center gap-1.5 shadow-lg shadow-red-100 uppercase">
                        <AlertCircle size={10}/> REVISIÓN
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-2">
           {!isMinimized && (
             <span className={`text-[9px] font-black px-2.5 py-1 rounded-lg border shadow-sm transition-all uppercase tracking-widest ${PRIORITY_STYLES[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1.5 text-slate-300 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-all"
           >
               {isMinimized ? <ChevronDown size={16}/> : <ChevronUp size={16}/>}
           </button>
        </div>
      </div>

      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-5 pr-12' : 'flex flex-col'}`}>
        <h3 className={`font-black text-slate-800 leading-snug tracking-tight group-hover:text-indigo-600 transition-colors 
            ${isMinimized ? 'text-xs truncate flex-1 uppercase' : 'text-[15px] mb-3 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/80 p-4 rounded-xl border border-slate-100/50 mb-4 overflow-hidden shadow-inner">
                <p className="text-xs text-slate-500 leading-relaxed line-clamp-2 font-medium italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {!isMinimized ? (
          <div className="mt-auto pt-4 border-t border-slate-100/80 flex flex-col gap-3 shrink-0">
             <div className="flex items-center justify-between">
                <div className="flex flex-col gap-1">
                    <div className="flex items-center gap-2 text-[10px] font-black text-indigo-500 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded-md w-fit">
                        <MapPin size={11} strokeWidth={3} /> {data.area}
                    </div>
                    <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400 uppercase tracking-tighter max-w-[160px]">
                        <Building2 size={11} className="opacity-40" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-1.5">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-2 bg-indigo-600 text-white px-3 py-1 rounded-xl text-[9px] font-black border border-indigo-700 shadow-xl shadow-indigo-100" title="Responsable Técnico">
                            <UserIcon size={10} strokeWidth={3} />
                            <span className="truncate max-w-[80px] uppercase">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-2 text-slate-400 font-mono text-[10px] font-black bg-slate-50 px-2.5 py-1 rounded-lg border border-slate-100">
                            <Clock size={11} strokeWidth={3} />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          <div className="absolute right-12 top-1/2 -translate-y-1/2 flex items-center gap-3 pointer-events-none opacity-40">
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{data.area}</span>
              <div className={`w-2 h-2 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]' : 'bg-slate-300'}`}></div>
          </div>
      )}
    </div>
  );
};

