import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area, UserRole } from '../types';
import { Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown, LayoutGrid } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, updateStatus, globalFilterArea, setGlobalFilterArea, activeRole, canUserSeeRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        alert(`RESTRICCIÓN DE FLUJO SISREQ:\n${err.message}`);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={18} />, color: 'indigo' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} />, color: 'orange' },
    { title: 'Ejecución Técnica', status: Status.EJECUCION, icon: <PlayCircle size={18} />, color: 'amber' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={18} />, color: 'emerald' }
  ];

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <div className="px-4 sm:px-8 py-4 sm:py-6 flex flex-col lg:flex-row lg:items-center justify-between gap-4 bg-white/50 backdrop-blur-sm border-b border-slate-200/50 shadow-sm z-20">
          <div className="flex items-center gap-4 sm:gap-6">
             <div className="flex flex-col">
                 <div className="flex items-center gap-2 sm:gap-3 mb-1">
                    <div className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    <h2 className="text-[8px] sm:text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] sm:tracking-[0.3em] leading-none">
                        Tablero de Operaciones
                    </h2>
                 </div>
                 <div className="flex items-center gap-3 sm:gap-4">
                    <span className="text-lg sm:text-2xl font-black text-slate-900 tracking-tighter">Ciclo de Vida</span>
                    <span className="bg-indigo-50 text-indigo-600 px-2 sm:px-3 py-0.5 sm:py-1 rounded-lg text-[9px] sm:text-[10px] font-black border border-indigo-100 shadow-sm">
                        {filteredRequests.length} <span className="hidden xs:inline">REQUERIMIENTOS</span>
                    </span>
                 </div>
             </div>
          </div>

          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 sm:gap-4">
             <div className="relative group flex-1 sm:flex-initial">
                <Search size={14} className="absolute left-3 sm:left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar..." 
                    className="w-full lg:min-w-[300px] pl-10 sm:pl-12 pr-4 sm:pr-6 py-2 sm:py-3 text-xs sm:text-sm font-bold bg-white border-2 border-slate-100 rounded-xl sm:rounded-2xl focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-300 shadow-inner"
                />
             </div>

             {(activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                <div className="relative">
                    <LayoutGrid size={14} className="absolute left-3 sm:left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="w-full pl-10 sm:pl-12 pr-8 sm:pr-10 py-2 sm:py-3 text-[10px] sm:text-xs font-black bg-white border-2 border-slate-100 rounded-xl sm:rounded-2xl appearance-none cursor-pointer outline-none focus:border-indigo-500 transition-all uppercase tracking-[0.1em] text-slate-600 shadow-sm"
                    >
                        <option value="ALL">Jurisdicción Global</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a.toUpperCase()}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-3 sm:right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar bg-slate-50/30">
          <div className="h-full flex px-4 sm:px-8 py-6 sm:py-10 gap-6 sm:gap-10 min-w-max">
              {COLUMNS.map((col) => {
                  if (col.status === Status.RECIBIDO && activeRole !== UserRole.ADMIN && activeRole !== UserRole.SUPERADMIN) return null;

                  const items = filteredRequests.filter(r => r.status === col.status);
                  const isDragActive = dragOverColumn === col.status;

                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col w-[280px] sm:w-[320px] lg:w-[380px] rounded-[2rem] sm:rounded-[3rem] transition-all duration-300 ${isDragActive ? 'bg-indigo-50/70 ring-2 ring-indigo-200 ring-dashed scale-[1.01]' : 'bg-transparent'}`} 
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                          onDragLeave={() => setDragOverColumn(null)} 
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          <div className="flex items-center justify-between px-5 sm:px-8 py-3 sm:py-5 bg-white border border-slate-100 rounded-2xl sm:rounded-3xl mb-4 sm:mb-8 shadow-sm ring-1 ring-black/5 shrink-0">
                              <div className="flex items-center gap-3 sm:gap-4">
                                  <div className={`p-2 sm:p-3 rounded-xl sm:rounded-2xl bg-${col.color}-50 text-${col.color}-600 shadow-inner`}>{col.icon}</div>
                                  <span className={`text-[9px] sm:text-[11px] font-black uppercase tracking-[0.15em] sm:tracking-[0.2em] text-slate-700`}>{col.title}</span>
                              </div>
                              <span className="bg-slate-100 text-slate-500 px-2 sm:px-3 py-1 sm:py-1.5 rounded-lg sm:rounded-xl text-[9px] sm:text-[10px] font-black border border-slate-200">{items.length}</span>
                          </div>

                          <div className="flex-1 overflow-y-auto px-1 sm:px-2 pb-20 sm:pb-24 custom-scrollbar space-y-4 sm:space-y-6">
                              {items.map(req => <RequestCard key={req.id} data={req} />)}
                              {items.length === 0 && (
                                  <div className="flex flex-col items-center justify-center h-40 sm:h-48 border-2 sm:border-4 border-dashed border-slate-200/50 rounded-[2rem] sm:rounded-[3rem] text-slate-300">
                                      <div className="mb-2 sm:mb-4 opacity-10 transform scale-125">{col.icon}</div>
                                      <p className="text-[8px] sm:text-[10px] font-black uppercase tracking-[0.2em] sm:tracking-[0.3em] opacity-40">Sin Pendientes</p>
                                  </div>
                              )}
                          </div>
                      </div>
                  )
              })}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, PRIORITY_STYLES } from '../constants';
import { UserRole, Status, Area } from '../types';
import { 
    X, User, Building, Clock, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Hash, PlayCircle, Trash2,
    ShieldAlert, UserCheck, History, ClipboardList, PenTool,
    ArrowRightCircle, CornerUpLeft, Trash
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    deleteRequest,
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole,
    canUserTransition
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
        setActionError(null);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data || !currentUser) return null;

  const handleClose = () => setSelectedRequestId(null);
  const isFinalized = data.status === Status.FINALIZADO;

  const handleTransition = async (targetStatus: Status) => {
    setActionError(null);
    try {
        await updateStatus(data.id, targetStatus);
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleReturnSubmit = async () => {
    if (returnReason.trim()) {
      try {
        await returnRequest(data.id, returnReason);
        setShowReturnInput(false);
        setReturnReason('');
      } catch (e: any) {
        setActionError(e.message);
      }
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleSaveChanges = async () => {
    if (editTitle.trim() && editDetail.trim()) {
        await updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleAddComment = async () => {
    if (newComment.trim()) {
        await addLog(data.id, `MENSAJE TÉCNICO: ${newComment}`);
        setNewComment('');
    }
  };

  const handleDelete = async () => {
    if (window.confirm("¿Está seguro de eliminar este requerimiento permanentemente?")) {
        await deleteRequest(data.id);
        handleClose();
    }
  };

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    (u.status === 'ACTIVE' || !u.status)
  );

  const canDeriveUI = canUserTransition(data, Status.DERIVACION).allowed;
  const canExecuteUI = canUserTransition(data, Status.EJECUCION).allowed;
  const canFinalizeUI = canUserTransition(data, Status.FINALIZADO).allowed;
  const canEditUI = activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN;
  const canDeleteUI = activeRole === UserRole.SUPERADMIN;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-2 sm:p-4">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[2rem] sm:rounded-[3rem] shadow-2xl w-full max-w-2xl max-h-[96vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[8px] sm:border-t-[14px] ${isFinalized ? 'border-emerald-500' : 'border-indigo-600'}`}>

        {/* Header */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 sm:px-8 sm:py-7 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3 sm:gap-5 min-w-0">
             <div className={`p-2.5 sm:p-4 rounded-xl sm:rounded-2xl text-white shrink-0 shadow-lg ${isFinalized ? 'bg-emerald-600' : 'bg-slate-800'}`}>
                {isFinalized ? <CheckCircle2 size={18} className="sm:w-6 sm:h-6" strokeWidth={2.5}/> : <ClipboardList size={18} className="sm:w-6 sm:h-6" strokeWidth={2.5} />}
             </div>
             <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-1.5 sm:gap-2 mb-0.5 sm:mb-1.5">
                    <span className={`px-2 py-0.5 sm:px-3 sm:py-1 rounded-lg text-[8px] sm:text-[10px] font-black uppercase tracking-wider shadow-sm ring-1 ring-black/5 ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="text-[8px] sm:text-[10px] text-slate-400 font-mono font-black bg-white px-1.5 py-0.5 sm:py-1 rounded border border-slate-100 flex items-center gap-1">
                        <Hash size={10} className="opacity-40"/>{data.id.split('-')[1].toUpperCase()}
                    </span>
                </div>
                {isEditing ? (
                    <input 
                        value={editTitle}
