                    <h2 className="text-xs sm:text-xl font-black text-slate-900 truncate uppercase tracking-tight leading-none">{data.title}</h2>
                )}
             </div>
          </div>
          <button onClick={handleClose} className="p-2 sm:p-3 text-slate-300 hover:text-slate-900 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100">
            <X size={20} className="sm:w-6 sm:h-6" />
          </button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto p-5 sm:p-10 space-y-8 sm:space-y-12 bg-white custom-scrollbar">

            {/* Main Info */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-8">
                <div className="bg-slate-50 p-4 sm:p-6 rounded-[1.5rem] border border-slate-100">
