                        <span className="text-xs sm:text-sm font-black text-slate-800 uppercase tracking-tight">{data.requester}</span>
                    </div>
                </div>
                <div className="bg-slate-50 p-4 sm:p-6 rounded-[1.5rem] border border-slate-100">
