            </div>

            {/* Description */}
            <div className="space-y-3 sm:space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <PenTool size={14} className="text-indigo-500"/> Descripción Técnica
                    </label>
                    {canEditUI && !isEditing && (
                        <button onClick={() => setIsEditing(true)} className="text-[9px] sm:text-[10px] font-black text-indigo-600 uppercase hover:underline">Editar</button>
                    )}
                </div>
                {isEditing ? (
                    <textarea 
                        value={editDetail}
                        onChange={e => setEditDetail(e.target.value)}
                        className="w-full bg-slate-50 border-2 border-indigo-100 p-4 sm:p-6 rounded-[1.5rem] sm:rounded-[2rem] text-sm text-slate-700 leading-relaxed outline-none min-h-[120px] sm:min-h-[160px] font-medium shadow-inner"
                    />
                ) : (
                    <div className="bg-slate-50/50 p-4 sm:p-8 rounded-[1.5rem] sm:rounded-[2rem] border border-slate-100/50 shadow-inner">
                        <p className="text-xs sm:text-[15px] text-slate-600 leading-relaxed font-medium italic">{data.detail}</p>
                    </div>
                )}
                {isEditing && (
                    <div className="flex justify-end gap-3">
                        <button onClick={() => setIsEditing(false)} className="px-4 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">Cancelar</button>
                        <button onClick={handleSaveChanges} className="px-6 py-2 bg-indigo-600 text-white text-[10px] font-black uppercase tracking-widest rounded-xl shadow-lg shadow-indigo-100">Guardar Cambios</button>
