               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1.5 sm:p-2 text-slate-300 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-all active:scale-90"
                aria-label={isMinimized ? "Expandir" : "Contraer"}
           >
               {isMinimized ? <ChevronDown size={14} className="sm:w-4 sm:h-4"/> : <ChevronUp size={14} className="sm:w-4 sm:h-4"/>}
           </button>
        </div>
      </div>

      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-3 sm:gap-5 pr-12' : 'flex flex-col'}`}>
        <h3 className={`font-black text-slate-800 leading-snug tracking-tight group-hover:text-indigo-600 transition-colors 
            ${isMinimized ? 'text-[10px] sm:text-xs truncate flex-1 uppercase' : 'text-xs sm:text-[15px] mb-2 sm:mb-3 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/80 p-2.5 sm:p-4 rounded-xl border border-slate-100/50 mb-3 sm:mb-4 overflow-hidden shadow-inner">
                <p className="text-[10px] sm:text-xs text-slate-500 leading-relaxed line-clamp-2 font-medium italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {!isMinimized ? (
          <div className="mt-auto pt-3 sm:pt-4 border-t border-slate-100/80 flex flex-col gap-2 sm:gap-3 shrink-0">
             <div className="flex flex-col xs:flex-row xs:items-center justify-between gap-2">
                <div className="flex flex-col gap-1">
                    <div className="flex items-center gap-1.5 text-[8px] sm:text-[10px] font-black text-indigo-500 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded-md w-fit">
                        <MapPin size={9} strokeWidth={3} /> {data.area}
                    </div>
                    <div className="flex items-center gap-1.5 text-[8px] sm:text-[10px] font-bold text-slate-400 uppercase tracking-tighter max-w-full xs:max-w-[140px]">
                        <Building2 size={9} className="opacity-40" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex items-center xs:flex-col xs:items-end gap-1.5">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1.5 bg-indigo-600 text-white px-2 py-0.5 sm:px-3 sm:py-1 rounded-xl text-[8px] sm:text-[9px] font-black border border-indigo-700 shadow-md shadow-indigo-100" title="Responsable Técnico">
                            <UserIcon size={9} strokeWidth={3} />
                            <span className="truncate max-w-[80px] uppercase">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-1.5 text-slate-400 font-mono text-[8px] sm:text-[10px] font-black bg-slate-50 px-2 py-0.5 rounded-lg border border-slate-100">
                            <Clock size={9} strokeWidth={3} />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          <div className="absolute right-10 sm:right-12 top-1/2 -translate-y-1/2 flex items-center gap-2 pointer-events-none opacity-40">
              <span className="text-[8px] sm:text-[10px] font-black text-slate-500 uppercase tracking-[0.1em] hidden sm:inline">{data.area}</span>
              <div className={`w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]' : 'bg-slate-300'}`}></div>
          </div>
      )}
    </div>
  );
};

export enum UserRole {
  SUPERADMIN = 'SUPERADMIN', // Auditoría y Control Maestro
  ADMIN = 'ADMIN',           // Gestión Central: Recepción y Derivación
  HEAD = 'HEAD',            // Jefatura de Área: Gestión de Recursos y Asignación
  ANALYST = 'ANALYST'       // Cuerpo Técnico: Ejecución y Resolución
}

export enum Area {
  CONTABILIDAD = 'Contabilidad',
  RRHH = 'RRHH',
  ACREDITACION = 'Acreditación',
  FINANZAS = 'Finanzas'
}

export enum Status {
  RECIBIDO = 'Recibido',      // Bandeja de Entrada Central (Admin)
  DERIVACION = 'En Derivación', // Asignado a un Área (Jefe de Área)
  EJECUCION = 'En Ejecución',   // En trabajo activo por un Analista
  FINALIZADO = 'Finalizado'     // Requerimiento resuelto y auditado
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export type UserStatus = 'ACTIVE' | 'INACTIVE';
export type ViewMode = 'work' | 'superadmin';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  area?: Area; 
  password?: string;
  status?: UserStatus;
  joinedAt?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
  role: UserRole;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; 
  assignedAnalyst?: string; 
  logs: LogEntry[];
  createdAt: string;
  lastUpdated: string;
  finishedAt?: string;
  isReturned?: boolean; 
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        console.error("CRITICAL: SISREQ Storage Layer Failure", error);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    if (user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN) {
      setGlobalFilterArea('ALL');
    } else {
      setGlobalFilterArea(user.area as Area);
    }
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;

    // El SuperAdmin ve todo. El Admin Central ve todo.
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;

    // Jefes y Analistas ven solo su área si ya ha sido derivada de Central.
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;

    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no identificada.' };
    if (req.status === target) return { allowed: true };

    // SuperAdmin tiene bypass total
    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    // Regla de Oro: Un ticket finalizado no se toca a menos que seas SuperAdmin
    if (req.status === Status.FINALIZADO && activeRole !== UserRole.SUPERADMIN) {
      return { allowed: false, reason: 'Solo Auditoría Superior puede reabrir requerimientos cerrados.' };
    }

    switch (activeRole) {
      case UserRole.ADMIN:
        // Admin Central: Solo puede derivar lo recibido o cerrar por excepción
        if (req.status === Status.RECIBIDO && target === Status.DERIVACION) return { allowed: true };
        if (target === Status.FINALIZADO && req.status === Status.EJECUCION) return { allowed: true };
        return { allowed: false, reason: 'Facultad administrativa limitada a recepción y derivación central.' };

      case UserRole.HEAD:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena.' };

        // Derivación -> Ejecución: Requiere analista asignado
        if (req.status === Status.DERIVACION && target === Status.EJECUCION) {
          if (!req.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un analista técnico antes de iniciar ejecución.' };
          return { allowed: true };
        }
        // Ejecución -> Finalizado: Permitido para Jefes
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'Transición no permitida según protocolo de Jefatura.' };

      case UserRole.ANALYST:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Acceso denegado a requerimientos de otras áreas.' };
        // Analista solo puede finalizar lo que está ejecutando
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'El cuerpo analista solo tiene facultades de resolución técnica.' };

      default:
        return { allowed: false, reason: 'Rol sin facultades operativas definidas.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: Status.RECIBIDO,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro formal de requerimiento en sistema central',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const isReturningToCentral = newStatus === Status.RECIBIDO;

    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      // Si vuelve a central, limpiamos el analista pero mantenemos el historial en logs
      assignedAnalyst: isReturningToCentral ? undefined : req.assignedAnalyst,
      isReturned: isReturningToCentral ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ESTADO: Cambio de fase operativa a [${newStatus.toUpperCase()}]`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN: Ticket regresado a Central por: ${reason}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN: Analista técnico [${analystName}] designado como responsable`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: message.trim(),
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'EDICIÓN: El contenido técnico del ticket ha sido actualizado',
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = {
      id: genId('U'),
      name: name.trim(),
      email: email.trim(),
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

