            {/* Quick Notes Form */}
            {!isFinalized && (
                <div className="space-y-3 sm:space-y-4 pt-4 border-t border-slate-100">
                    <label className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <MessageSquare size={14} className="text-indigo-500"/> Apunte Técnico
                    </label>
                    <div className="flex gap-2">
                        <input 
                            value={newComment}
                            onChange={e => setNewComment(e.target.value)}
                            placeholder="Añadir comentario interno al expediente..."
                            className="flex-1 bg-slate-50 border-2 border-slate-100 px-4 py-3 rounded-xl text-xs sm:text-sm outline-none focus:border-indigo-400 transition-all font-medium"
                        />
                        <button onClick={handleAddComment} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 shrink-0">
                            <Send size={18} strokeWidth={2.5}/>
                        </button>
                    </div>
                </div>
            )}
        </div>

        {/* Action Tray Footer */}
        <div className="bg-white border-t border-slate-100 p-4 sm:p-8 shrink-0 flex flex-col gap-4">
            {actionError && (
                <div className="bg-red-50 text-red-600 p-3 sm:p-4 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border border-red-100 animate-in shake">
                    <ShieldAlert size={16}/> {actionError}
                </div>
            )}

            {showAnalystSelect ? (
                <div className="space-y-3 animate-in slide-in-from-bottom-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block text-center">Designar Personal Analista</label>
                    <div className="flex flex-wrap justify-center gap-2">
                        {availableAssignees.map(u => (
                            <button 
                                key={u.id} 
                                onClick={() => handleAssignAnalyst(u.name)}
                                className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${data.assignedAnalyst === u.name ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-500 hover:bg-indigo-50'}`}
                            >
                                {u.name}
                            </button>
                        ))}
                        <button onClick={() => setShowAnalystSelect(false)} className="px-4 py-2 rounded-xl text-[10px] font-black uppercase text-slate-400 bg-slate-50">Cerrar</button>
                    </div>
                </div>
            ) : showReturnInput ? (
                <div className="space-y-3 animate-in slide-in-from-bottom-2">
                    <label className="text-[10px] font-black text-red-400 uppercase tracking-widest block text-center">Fundamentar Devolución</label>
                    <div className="flex gap-2">
                        <input 
                            value={returnReason} 
                            onChange={e => setReturnReason(e.target.value)} 
                            className="flex-1 bg-red-50/50 border-2 border-red-100 px-4 py-3 rounded-xl text-sm outline-none focus:border-red-500 transition-all"
                            placeholder="Explique el motivo del retorno..."
                        />
                        <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest">Regresar</button>
                        <button onClick={() => setShowReturnInput(false)} className="bg-slate-100 text-slate-400 px-4 py-2 rounded-xl text-[10px] font-black uppercase">Cancelar</button>
                    </div>
                </div>
            ) : (
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4">
                    <div className="flex items-center gap-2">
                        <button onClick={handleClose} className="hidden sm:flex px-6 py-3 text-slate-400 font-black text-[10px] uppercase tracking-widest hover:bg-slate-50 rounded-2xl transition-all">Regresar</button>
                        {canDeleteUI && (
                            <button onClick={handleDelete} className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all border border-transparent hover:border-red-100" title="Eliminar Registro">
                                <Trash size={20}/>
                            </button>
                        )}
                    </div>

                    <div className="flex flex-col sm:flex-row items-stretch gap-2.5">
                        {/* Mobile view stacked buttons */}
                        {data.status !== Status.RECIBIDO && activeRole !== UserRole.ANALYST && !isFinalized && (
                            <button 
                                onClick={() => setShowReturnInput(true)}
                                className="px-6 py-4 bg-white border-2 border-red-100 text-red-600 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-red-50 transition-all active:scale-95"
                            >
                                <CornerUpLeft size={16}/> Devolver a Central
                            </button>
                        )}

                        {canDeriveUI && (
                            <button 
                                onClick={() => setShowAnalystSelect(true)}
                                className="px-6 py-4 bg-white border-2 border-orange-200 text-orange-600 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-orange-50 transition-all active:scale-95"
                            >
                                <UserCheck size={16}/> {data.assignedAnalyst ? 'Reasignar' : 'Designar Técnico'}
                            </button>
                        )}

                        {canExecuteUI && (
                            <button 
                                onClick={() => handleTransition(Status.EJECUCION)}
                                className="px-8 py-4 bg-amber-500 hover:bg-amber-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-amber-100 flex items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                <PlayCircle size={16} strokeWidth={3}/> Iniciar Ejecución
                            </button>
                        )}

                        {canFinalizeUI && (
                            <button 
                                onClick={() => handleTransition(Status.FINALIZADO)}
                                className="px-10 py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 flex items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                <CheckCircle2 size={16} strokeWidth={3}/> Finalizar Proceso
                            </button>
                        )}

                        {isFinalized && activeRole === UserRole.SUPERADMIN && (
                            <button 
                                onClick={() => handleTransition(Status.EJECUCION)}
                                className="px-10 py-4 bg-slate-800 hover:bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-slate-200 flex items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                <RotateCcw size={16} strokeWidth={3}/> Reabrir Expediente
                            </button>
                        )}

                        <button onClick={handleClose} className="sm:hidden px-6 py-4 bg-slate-100 text-slate-500 font-black text-[10px] uppercase tracking-widest rounded-2xl transition-all">Cerrar Detalle</button>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export enum UserRole {
  SUPERADMIN = 'SUPERADMIN', // Auditoría y Control Maestro
  ADMIN = 'ADMIN',           // Gestión Central: Recepción y Derivación
  HEAD = 'HEAD',            // Jefatura de Área: Gestión de Recursos y Asignación
  ANALYST = 'ANALYST'       // Cuerpo Técnico: Ejecución y Resolución
}

export enum Area {
  CONTABILIDAD = 'Contabilidad',
  RRHH = 'RRHH',
  ACREDITACION = 'Acreditación',
  FINANZAS = 'Finanzas'
}

export enum Status {
  RECIBIDO = 'Recibido',      // Bandeja de Entrada Central (Admin)
  DERIVACION = 'En Derivación', // Asignado a un Área (Jefe de Área)
  EJECUCION = 'En Ejecución',   // En trabajo activo por un Analista
  FINALIZADO = 'Finalizado'     // Requerimiento resuelto y auditado
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export type UserStatus = 'ACTIVE' | 'INACTIVE';
export type ViewMode = 'work' | 'superadmin';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  area?: Area; 
  password?: string;
  status?: UserStatus;
  joinedAt?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
  role: UserRole;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; 
  assignedAnalyst?: string; 
  logs: LogEntry[];
  createdAt: string;
  lastUpdated: string;
  finishedAt?: string;
  isReturned?: boolean; 
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, ViewMode } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  viewMode: ViewMode;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  setViewMode: (mode: ViewMode) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('work');
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        console.error("CRITICAL: SISREQ Storage Layer Failure", error);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    if (user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN) {
      setGlobalFilterArea('ALL');
    } else {
      setGlobalFilterArea(user.area as Area);
    }
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
    setViewMode('work');
  };

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;

    // Regla de Visibilidad Global: SuperAdmin y Admin Central ven todo el circuito.
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;

    // Jefes y Analistas ven solo su área si el ticket ya salió de la Bandeja Central.
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;

    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no identificada.' };
    if (req.status === target) return { allowed: true };

    // El SuperAdmin puede forzar cualquier transición para corrección de datos.
    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    // Regla de Oro: Un ticket finalizado es inmutable para roles operativos.
    if (req.status === Status.FINALIZADO && activeRole !== UserRole.SUPERADMIN) {
      return { allowed: false, reason: 'Solo Auditoría Superior puede reabrir requerimientos cerrados.' };
    }

    switch (activeRole) {
      case UserRole.ADMIN:
        // Admin Central: Gestiona la recepción y derivación.
        if (req.status === Status.RECIBIDO && target === Status.DERIVACION) return { allowed: true };
        if (target === Status.FINALIZADO && req.status === Status.RECIBIDO) return { allowed: true }; // Cancelación central
        return { allowed: false, reason: 'Facultad central limitada a derivación inicial.' };

      case UserRole.HEAD:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena.' };

        // Derivación -> Ejecución: Requiere analista asignado.
        if (req.status === Status.DERIVACION && target === Status.EJECUCION) {
          if (!req.assignedAnalyst) return { allowed: false, reason: 'Debe designar un analista técnico antes de iniciar.' };
          return { allowed: true };
        }
        // Ejecución -> Finalizado: Permitido para Jefes.
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'Transición bloqueada por protocolo de Jefatura.' };

      case UserRole.ANALYST:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena.' };
        // Analista solo puede finalizar lo que está bajo su ejecución técnica.
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) {
            if (req.assignedAnalyst !== currentUser.name) return { allowed: false, reason: 'Solo el analista asignado puede certificar el cierre.' };
            return { allowed: true };
        }
        return { allowed: false, reason: 'El cuerpo analista solo tiene facultades de resolución técnica.' };

      default:
        return { allowed: false, reason: 'Rol sin facultades operativas definidas.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title: title.trim(),
      detail: detail.trim(),
      area,
      status: Status.RECIBIDO,
      priority,
      requester: requester.trim(),
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro formal de requerimiento en sistema central',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const isReturningToCentral = newStatus === Status.RECIBIDO;

    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      // Limpieza de responsabilidades al volver a central.
      assignedAnalyst: isReturningToCentral ? undefined : req.assignedAnalyst,
      isReturned: isReturningToCentral ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ESTADO: Cambio de fase operativa a [${newStatus.toUpperCase()}]`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN: Ticket regresado a Central. Motivo: ${reason}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN: Designado responsable técnico [${analystName}]`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: message.trim(),
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title: title.trim(),
      detail: detail.trim(),
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'EDICIÓN: Actualización de especificaciones técnicas del requerimiento',
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = {
      id: genId('U'),
      name: name.trim(),
      email: email.trim(),
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, viewMode, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, setViewMode, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area, UserRole } from '../types';
import { Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown, LayoutGrid } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, updateStatus, globalFilterArea, setGlobalFilterArea, activeRole, canUserSeeRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
