          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { PRIORITY_STYLES } from '../constants';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2, AlertCircle } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId, activeRole } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  const isDraggable = () => {
    if (!currentUser || !activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN) return true;

    // Admin puede arrastrar solo lo recibido
    if (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) return true;

    // Jefes y Analistas en su área
    if (data.area === currentUser.area) {
        if (activeRole === UserRole.HEAD) {
            // Jefe puede mover de Derivación a Ejecución si hay analista
            if (data.status === Status.DERIVACION && !!data.assignedAnalyst) return true;
            if (data.status === Status.EJECUCION) return true;
        }
        if (activeRole === UserRole.ANALYST && data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    if (!isDraggable()) {
        e.preventDefault();
        return;
    }
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';

    const dragGhost = e.currentTarget as HTMLElement;
    dragGhost.style.opacity = '0.4';
    setTimeout(() => {
        if (dragGhost) dragGhost.style.opacity = '1';
    }, 0);
  };

  const handleCardClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-500';
        case Status.DERIVACION: return 'border-orange-500';
        case Status.EJECUCION: return 'border-amber-500';
        case Status.FINALIZADO: return 'border-emerald-500';
        default: return 'border-slate-300';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-2xl sm:rounded-[2rem] relative group animate-in fade-in slide-in-from-bottom-2 duration-300
            transition-all duration-300 ease-out
            shadow-[0_4px_15px_-10px_rgba(0,0,0,0.1)] hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.15)]
            border border-slate-100
            border-l-[6px] sm:border-l-[8px]
            cursor-pointer flex flex-col overflow-hidden
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'hover:bg-indigo-50/10 active:scale-[0.98]' : 'cursor-default'}
            ${isMinimized ? 'h-auto py-3 px-4 sm:px-6' : 'min-h-[160px] sm:min-h-[190px] p-4 sm:p-6'}
        `}
    >
      {/* Header Info */}
      <div className={`flex justify-between items-start shrink-0 ${isMinimized ? '' : 'mb-3 sm:mb-4'}`}>
        <div className="flex items-center gap-2 sm:gap-3">
            {isDraggable() && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="hidden sm:block p-1 -ml-2 text-slate-200 group-hover:text-indigo-400 cursor-grab active:cursor-grabbing transition-colors">
                    <GripVertical size={14} />
                </div>
            )}
            <div className="flex flex-wrap items-center gap-1.5 sm:gap-2">
                <span className="flex items-center gap-1 font-mono text-[8px] sm:text-[10px] text-slate-400 font-black uppercase tracking-tighter">
                    <Hash size={10} className="opacity-40" /> {data.id.split('-')[1]}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[7px] sm:text-[9px] bg-red-600 text-white px-1.5 py-0.5 rounded-md font-black tracking-widest flex items-center gap-1 shadow-lg shadow-red-100 uppercase">
                        <AlertCircle size={9}/> <span className="hidden xs:inline">REVISIÓN</span>
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-1.5">
           {!isMinimized && (
             <span className={`text-[7px] sm:text-[9px] font-black px-1.5 py-0.5 sm:px-2.5 sm:py-1 rounded-lg border shadow-sm transition-all uppercase tracking-widest ${PRIORITY_STYLES[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1.5 sm:p-2 text-slate-300 hover:text-slate-600 hover:bg-slate-100 rounded-lg transition-all active:scale-90"
                aria-label={isMinimized ? "Expandir" : "Contraer"}
           >
               {isMinimized ? <ChevronDown size={14} className="sm:w-4 sm:h-4"/> : <ChevronUp size={14} className="sm:w-4 sm:h-4"/>}
           </button>
        </div>
      </div>

      {/* Main Content */}
      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-3 sm:gap-5 pr-12' : 'flex flex-col'}`}>
        <h3 className={`font-black text-slate-800 leading-snug tracking-tight group-hover:text-indigo-600 transition-colors 
            ${isMinimized ? 'text-[10px] sm:text-xs truncate flex-1 uppercase' : 'text-xs sm:text-[15px] mb-2 sm:mb-3 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/80 p-2.5 sm:p-4 rounded-xl border border-slate-100/50 mb-3 sm:mb-4 overflow-hidden shadow-inner">
                <p className="text-[10px] sm:text-xs text-slate-500 leading-relaxed line-clamp-2 font-medium italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {/* Card Footer / Metadata */}
      {!isMinimized ? (
          <div className="mt-auto pt-3 sm:pt-4 border-t border-slate-100/80 flex flex-col gap-2 sm:gap-3 shrink-0">
             <div className="flex flex-col xs:flex-row xs:items-center justify-between gap-2">
                <div className="flex flex-col gap-1">
                    <div className="flex items-center gap-1.5 text-[8px] sm:text-[10px] font-black text-indigo-500 uppercase tracking-widest bg-indigo-50 px-2 py-0.5 rounded-md w-fit">
                        <MapPin size={9} strokeWidth={3} /> {data.area}
                    </div>
                    <div className="flex items-center gap-1.5 text-[8px] sm:text-[10px] font-bold text-slate-400 uppercase tracking-tighter max-w-full xs:max-w-[140px]">
                        <Building2 size={9} className="opacity-40" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex items-center xs:flex-col xs:items-end gap-1.5">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1.5 bg-indigo-600 text-white px-2 py-0.5 sm:px-3 sm:py-1 rounded-xl text-[8px] sm:text-[9px] font-black border border-indigo-700 shadow-md shadow-indigo-100" title="Responsable Técnico">
                            <UserIcon size={9} strokeWidth={3} />
                            <span className="truncate max-w-[80px] uppercase">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-1.5 text-slate-400 font-mono text-[8px] sm:text-[10px] font-black bg-slate-50 px-2 py-0.5 rounded-lg border border-slate-100">
                            <Clock size={9} strokeWidth={3} />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          <div className="absolute right-10 sm:right-12 top-1/2 -translate-y-1/2 flex items-center gap-2 pointer-events-none opacity-40">
              <span className="text-[8px] sm:text-[10px] font-black text-slate-500 uppercase tracking-[0.1em] hidden sm:inline">{data.area}</span>
              <div className={`w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]' : 'bg-slate-300'}`}></div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, PRIORITY_STYLES } from '../constants';
import { UserRole, Status, Area } from '../types';
import { 
    X, User, Building, Clock, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Hash, PlayCircle, Trash2,
    ShieldAlert, UserCheck, History, ClipboardList, PenTool,
