} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    deleteRequest,
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole,
    canUserTransition
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
        setActionError(null);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data || !currentUser) return null;

  const handleClose = () => setSelectedRequestId(null);
  const isFinalized = data.status === Status.FINALIZADO;

  const handleTransition = async (targetStatus: Status) => {
    setActionError(null);
    try {
        await updateStatus(data.id, targetStatus);
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleReturnSubmit = async () => {
    if (returnReason.trim()) {
      try {
        await returnRequest(data.id, returnReason);
        setShowReturnInput(false);
        setReturnReason('');
      } catch (e: any) {
        setActionError(e.message);
      }
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleSaveChanges = async () => {
    if (editTitle.trim() && editDetail.trim()) {
        await updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleAddComment = async () => {
    if (newComment.trim()) {
        await addLog(data.id, `MENSAJE TÉCNICO: ${newComment}`);
        setNewComment('');
    }
  };

  const handleDelete = async () => {
    if (window.confirm("¿Está seguro de eliminar este requerimiento permanentemente? Esta acción es irreversible.")) {
        await deleteRequest(data.id);
        handleClose();
    }
  };

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    (u.status === 'ACTIVE' || !u.status)
  );

  const canDeriveUI = canUserTransition(data, Status.DERIVACION).allowed;
  const canExecuteUI = canUserTransition(data, Status.EJECUCION).allowed;
  const canFinalizeUI = canUserTransition(data, Status.FINALIZADO).allowed;
  const canEditUI = activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN;
  const canDeleteUI = activeRole === UserRole.SUPERADMIN;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-2 sm:p-4">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[2rem] sm:rounded-[3rem] shadow-2xl w-full max-w-2xl max-h-[96vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[8px] sm:border-t-[14px] ${isFinalized ? 'border-emerald-500' : 'border-indigo-600'}`}>

        {/* Header Section */}
        <div className="bg-slate-50 border-b border-slate-100 px-6 py-4 sm:px-8 sm:py-7 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-3 sm:gap-5 min-w-0">
             <div className={`p-2.5 sm:p-4 rounded-xl sm:rounded-2xl text-white shrink-0 shadow-lg ${isFinalized ? 'bg-emerald-600' : 'bg-slate-800'}`}>
                {isFinalized ? <CheckCircle2 size={18} className="sm:w-6 sm:h-6" strokeWidth={2.5}/> : <ClipboardList size={18} className="sm:w-6 sm:h-6" strokeWidth={2.5} />}
             </div>
             <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-1.5 sm:gap-2 mb-0.5 sm:mb-1.5">
                    <span className={`px-2 py-0.5 sm:px-3 sm:py-1 rounded-lg text-[8px] sm:text-[10px] font-black uppercase tracking-wider shadow-sm ring-1 ring-black/5 ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="text-[8px] sm:text-[10px] text-slate-400 font-mono font-black bg-white px-1.5 py-0.5 sm:py-1 rounded border border-slate-100 flex items-center gap-1">
                        <Hash size={10} className="opacity-40"/>{data.id.split('-')[1].toUpperCase()}
                    </span>
                </div>
                {isEditing ? (
                    <input 
                        value={editTitle}
                        onChange={e => setEditTitle(e.target.value)}
                        className="text-sm sm:text-xl font-black text-slate-900 w-full bg-white border-b-2 border-indigo-500 outline-none uppercase tracking-tight"
                    />
                ) : (
                    <h2 className="text-xs sm:text-xl font-black text-slate-900 truncate uppercase tracking-tight leading-none">{data.title}</h2>
                )}
             </div>
          </div>
          <button onClick={handleClose} className="p-2 sm:p-3 text-slate-300 hover:text-slate-900 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100">
