                            <div className="min-w-0 flex-1">
                                <div className="flex items-center gap-2 mb-1 flex-wrap">
                                    <span className="text-[10px] font-black text-slate-800 uppercase tracking-tight">{log.actor}</span>
                                    <span className="text-[9px] font-bold text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-100 uppercase tracking-tighter">{log.role}</span>
                                    <span className="text-[9px] text-slate-300 font-mono ml-auto">{new Date(log.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                </div>
                                <p className="text-[11px] sm:text-xs text-slate-500 font-medium leading-relaxed">{log.message}</p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Annotations Section */}
            {!isFinalized && (
                <div className="space-y-3 sm:space-y-4 pt-4 border-t border-slate-100">
                    <label className="text-[9px] sm:text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <MessageSquare size={14} className="text-indigo-500"/> Notas Técnicas
                    </label>
                    <div className="flex gap-2">
                        <input 
                            value={newComment}
                            onChange={e => setNewComment(e.target.value)}
                            placeholder="Agregar apunte al registro técnico..."
                            className="flex-1 bg-slate-50 border-2 border-slate-100 px-4 py-3 rounded-xl text-xs sm:text-sm outline-none focus:border-indigo-400 transition-all font-medium"
                        />
                        <button onClick={handleAddComment} className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 shrink-0">
                            <Send size={18} strokeWidth={2.5}/>
                        </button>
                    </div>
                </div>
            )}
        </div>

        {/* Action Panel Footer */}
        <div className="bg-white border-t border-slate-100 p-4 sm:p-8 shrink-0 flex flex-col gap-4">
            {actionError && (
                <div className="bg-red-50 text-red-600 p-3 sm:p-4 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border border-red-100 animate-in shake">
                    <ShieldAlert size={16}/> {actionError}
                </div>
            )}

            {showAnalystSelect ? (
                <div className="space-y-4 animate-in slide-in-from-bottom-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block text-center">Seleccionar Analista Técnico</label>
                    <div className="flex flex-wrap justify-center gap-2">
                        {availableAssignees.map(u => (
                            <button 
                                key={u.id} 
                                onClick={() => handleAssignAnalyst(u.name)}
                                className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${data.assignedAnalyst === u.name ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-500 hover:bg-indigo-50'}`}
                            >
                                {u.name}
                            </button>
                        ))}
                        <button onClick={() => setShowAnalystSelect(false)} className="px-4 py-2 rounded-xl text-[10px] font-black uppercase text-slate-400 bg-slate-50">Cancelar</button>
                    </div>
                </div>
            ) : showReturnInput ? (
                <div className="space-y-4 animate-in slide-in-from-bottom-2">
                    <label className="text-[10px] font-black text-red-400 uppercase tracking-widest block text-center">Indique Justificación de Retorno</label>
                    <div className="flex gap-2">
                        <input 
                            value={returnReason} 
                            onChange={e => setReturnReason(e.target.value)} 
                            className="flex-1 bg-red-50/50 border-2 border-red-100 px-4 py-3 rounded-xl text-sm outline-none focus:border-red-500 transition-all"
                            placeholder="Ej: Información insuficiente..."
                        />
                        <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-red-100">Enviar</button>
                        <button onClick={() => setShowReturnInput(false)} className="bg-slate-100 text-slate-400 px-4 py-2 rounded-xl text-[10px] font-black uppercase">Cancelar</button>
                    </div>
                </div>
            ) : (
                <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4">
                    <div className="flex items-center gap-2">
                        <button onClick={handleClose} className="hidden sm:flex px-6 py-3 text-slate-400 font-black text-[10px] uppercase tracking-widest hover:bg-slate-50 rounded-2xl transition-all">Cerrar</button>
                        {canDeleteUI && (
                            <button onClick={handleDelete} className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all border border-transparent hover:border-red-100" title="Eliminar Definitivamente">
                                <Trash size={20}/>
                            </button>
                        )}
                    </div>

                    <div className="flex flex-col sm:flex-row items-stretch gap-2.5">
                        {data.status !== Status.RECIBIDO && activeRole !== UserRole.ANALYST && !isFinalized && (
                            <button 
                                onClick={() => setShowReturnInput(true)}
                                className="px-6 py-4 bg-white border-2 border-red-100 text-red-600 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-red-50 transition-all active:scale-95"
                            >
                                <CornerUpLeft size={16}/> Retornar a Central
                            </button>
                        )}

                        {canDeriveUI && (
                            <button 
                                onClick={() => setShowAnalystSelect(true)}
                                className="px-6 py-4 bg-white border-2 border-orange-200 text-orange-600 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-orange-50 transition-all active:scale-95"
                            >
                                <UserCheck size={16}/> {data.assignedAnalyst ? 'Reasignar Analista' : 'Asignar Analista'}
                            </button>
                        )}

                        {canExecuteUI && (
                            <button 
                                onClick={() => handleTransition(Status.EJECUCION)}
                                className="px-8 py-4 bg-amber-500 hover:bg-amber-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-amber-100 flex items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                <PlayCircle size={16} strokeWidth={3}/> Iniciar Resolución
                            </button>
                        )}

                        {canFinalizeUI && (
                            <button 
                                onClick={() => handleTransition(Status.FINALIZADO)}
                                className="px-10 py-4 bg-emerald-600 hover:bg-emerald-700 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-emerald-100 flex items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                <CheckCircle2 size={16} strokeWidth={3}/> Certificar Finalización
                            </button>
                        )}

                        {isFinalized && activeRole === UserRole.SUPERADMIN && (
                            <button 
                                onClick={() => handleTransition(Status.EJECUCION)}
                                className="px-10 py-4 bg-slate-800 hover:bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-slate-200 flex items-center justify-center gap-2 transition-all active:scale-95"
                            >
                                <RotateCcw size={16} strokeWidth={3}/> Reabrir Expediente
                            </button>
                        )}

                        {/* Mobile back button */}
                        <button onClick={handleClose} className="sm:hidden px-6 py-4 bg-slate-100 text-slate-500 font-black text-[10px] uppercase tracking-widest rounded-2xl transition-all">Regresar</button>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, Area } from '../types';
import { LayoutDashboard, Plus, Briefcase, LogOut, Shield, ArrowLeftRight } from 'lucide-react';
import { NewRequestModal } from './NewRequestModal';
import { RequestDetailModal } from './RequestDetailModal';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { currentUser, logout, viewMode, setViewMode, activeRole, setActiveRole, setGlobalFilterArea, setSelectedRequestId } = useSisreq();
  const [isModalOpen, setIsModalOpen] = useState(false);

  if (!currentUser) return null;

  const getInitials = (name: string) => name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);

  const isHybridUser = currentUser.role === UserRole.ADMIN && !!currentUser.area;

  const handleToggleProfile = () => {
    setSelectedRequestId(null);
    if (activeRole === UserRole.ADMIN) {
        setActiveRole(UserRole.HEAD);
        setGlobalFilterArea(currentUser.area as Area);
    } else {
        setActiveRole(UserRole.ADMIN);
        setGlobalFilterArea('ALL');
    }
  };

  const getRoleBadge = () => {
    if (isHybridUser) {
        return (
            <button 
                onClick={handleToggleProfile}
                className={`flex items-center gap-1.5 px-2 py-0.5 rounded-lg text-[9px] font-bold border transition-all ${
                    activeRole === UserRole.ADMIN 
                    ? 'bg-red-50 text-red-600 border-red-100 hover:bg-red-100' 
                    : 'bg-indigo-50 text-indigo-600 border-indigo-100 hover:bg-indigo-100'
                }`}
            >
                <ArrowLeftRight size={10} />
                {activeRole === UserRole.ADMIN ? 'MODO ADMIN' : `JEFE ${currentUser.area?.toUpperCase()}`}
            </button>
        );
    }

    switch (currentUser.role) {
        case UserRole.SUPERADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-900 text-white font-bold border border-slate-950 tracking-wider">SUPERADMIN</span>;
        case UserRole.ADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-red-50 text-red-600 font-bold border border-red-100 tracking-wider uppercase">ADMIN CENTRAL</span>;
        case UserRole.HEAD: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-indigo-50 text-indigo-600 font-bold border border-indigo-100 tracking-wider uppercase">JEFE {currentUser.area}</span>;
        default: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-100 text-slate-500 font-bold border border-slate-200 tracking-wider uppercase">ANALYST</span>;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 overflow-hidden font-sans">
      <header className="bg-white/90 backdrop-blur-xl border-b border-slate-200/60 z-30 shrink-0 h-16 px-4 sm:px-6 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-4 sm:gap-8">
            <div className="flex items-center gap-2 sm:gap-3 sm:pr-8 sm:border-r sm:border-slate-200/50">
                <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-100">
                    <LayoutDashboard size={18} sm:size={20} strokeWidth={2.5} />
                </div>
                <h1 className="text-base sm:text-lg font-black tracking-tighter text-slate-900 leading-none">SISREQ</h1>
            </div>

            <nav className="hidden md:flex items-center gap-6">
                {currentUser.role === UserRole.SUPERADMIN ? (
                    <div className="flex bg-slate-100 p-1 rounded-xl gap-1 border border-slate-200/50">
                        <button 
                            onClick={() => setViewMode('work')} 
                            className={`px-5 py-1.5 rounded-lg transition-all text-[10px] font-black uppercase tracking-widest ${viewMode === 'work' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                        >
                            Operativo
                        </button>
                        <button 
                            onClick={() => setViewMode('superadmin')} 
                            className={`px-5 py-1.5 rounded-lg transition-all text-[10px] font-black uppercase tracking-widest ${viewMode === 'superadmin' ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                        >
                            Master
                        </button>
                    </div>
                ) : (
                    <div className="flex items-center gap-2.5 px-4 py-1.5 bg-slate-50 rounded-full border border-slate-100">
                        {activeRole === UserRole.ADMIN ? <Shield size={14} className="text-red-500"/> : <Briefcase size={14} className="text-indigo-500"/>}
                        <span className="text-[10px] font-black uppercase tracking-[0.1em] text-slate-600">
                            {activeRole === UserRole.ADMIN ? 'Consola Central' : `${activeRole} • ${currentUser.area}`}
                        </span>
                    </div>
                )}
            </nav>
        </div>

        <div className="flex items-center gap-3 sm:gap-5">
            {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) && (
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-3 sm:px-5 py-2 rounded-xl flex items-center gap-2 text-[10px] font-black uppercase tracking-widest transition-all shadow-xl shadow-indigo-100 active:scale-95 group"
                >
                    <Plus size={16} strokeWidth={3} className="group-hover:rotate-90 transition-transform" /> 
                    <span className="hidden sm:inline">Nuevo Ticket</span>
                </button>
            )}

            <div className="hidden sm:block h-8 w-px bg-slate-200 mx-1"></div>

            <div className="flex items-center gap-3 sm:gap-4">
                <div className="flex flex-col items-end hidden xs:flex">
                    <span className="text-xs sm:text-sm font-black text-slate-800 leading-none mb-1">{currentUser.name.split(' ')[0]}</span>
                    {getRoleBadge()}
                </div>
                <div className="w-9 h-9 sm:w-10 sm:h-10 rounded-xl bg-slate-100 border border-white shadow-sm flex items-center justify-center font-black text-[10px] sm:text-xs text-slate-600 shrink-0 ring-4 ring-slate-50">
                    {getInitials(currentUser.name)}
                </div>
                <button 
                    onClick={logout} 
                    className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" 
                    title="Cerrar Sesión"
                >
                    <LogOut size={20} />
                </button>
            </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0 relative z-10">
        {children}
        <div className="absolute inset-0 opacity-[0.1] pointer-events-none z-[-1]" 
             style={{backgroundImage: 'radial-gradient(#94a3b8 1px, transparent 1px)', backgroundSize: '30px 30px'}}>
        </div>
      </main>

      <NewRequestModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      <RequestDetailModal />
    </div>
  );
};
